void parallelForces(Particle *particles, const size_t particleCount, const size_t start, const size_t end, const uint32_t *particleTable, float mass, float viscosity, float spikyGrad, float spikyLap, float h, float h2) {
    for (size_t piIndex = start; piIndex < end; piIndex++) {
        Particle* pi = &particles[piIndex];
        pi->force = glm::vec3(0);

        // Iterate over neighboring cells
        for (int x = -1; x <= 1; x++) {
            for (int y = -1; y <= 1; y++) {
                for (int z = -1; z <= 1; z++) {
                    // Calculate neighbor cell hash
                    glm::ivec3 neighborCell = getCell(pi, h) + glm::ivec3(x, y, z);
                    uint16_t cellHash = getHash(neighborCell);
                    uint32_t pjIndex = particleTable[cellHash];

                    if (pjIndex == NO_PARTICLE) {
                        continue;
                    }

                    // Iterate over particles in the neighbor cell
                    while (pjIndex < particleCount) {
                        if (pjIndex == piIndex) {
                            pjIndex++;
                            continue;
                        }
                        Particle *pj = &particles[pjIndex];
                        if (pj->hash != cellHash) {
                            break;
                        }

                        // Calculate distance and direction
                        glm::vec3 rij = pi->position - pj->position;
                        float dist2 = glm::dot(rij, rij);

                        if (dist2 < h2 && dist2 > 0.0f) {
                            float dist = std::sqrt(dist2);
                            glm::vec3 dir = rij / dist;

                            // Pressure force
                            float pressureTerm = (pi->pressure + pj->pressure) / (2.0f * pj->density);
                            float spikyGradTerm = spikyGrad * std::pow(h - dist, 2.0f);
                            glm::vec3 pressureForce = -mass * pressureTerm * spikyGradTerm * dir;

                            // Viscosity force
                            glm::vec3 velocityDif = pj->velocity - pi->velocity;
                            float spikyLapTerm = spikyLap * (h - dist);
                            glm::vec3 viscoForce = viscosity * mass * (velocityDif / pj->density) * spikyLapTerm;

                            // Accumulate forces
                            pi->force += pressureForce + viscoForce;
                        }
                        pjIndex++;
                    }
                }
            }
        }
    }
